(function () {
  var KEY = "site-lang";
  var nodes = [];
  document.querySelectorAll("body *:not(script):not(style)").forEach(function (el) {
    var html = el.innerHTML.trim();
    if (Object.prototype.hasOwnProperty.call(ES, html)) { el.setAttribute("data-en", html); nodes.push(el); }
  });
  var btn = document.getElementById("lang");

  function apply(lang) {
    nodes.forEach(function (el) { el.innerHTML = lang === "es" ? ES[el.getAttribute("data-en")] : el.getAttribute("data-en"); });
    document.documentElement.lang = lang;
    if (btn) {
      btn.innerHTML = lang === "es" ? '<b>ES</b> / EN' : 'ES / <b>EN</b>';
      btn.setAttribute("aria-label", lang === "es" ? "Switch to English" : "Cambiar a español");
    }
    try { localStorage.setItem(KEY, lang); } catch (e) {}
  }

  var saved = null;
  try { saved = localStorage.getItem(KEY); } catch (e) {}
  var lang = saved || ((navigator.language || "").toLowerCase().indexOf("es") === 0 ? "es" : "en");
  apply(lang);
  if (btn) btn.addEventListener("click", function () { lang = lang === "es" ? "en" : "es"; apply(lang); });
})();
